// Obtenemos los datos cacheados de Redis, si existen
const redisOutput = $('Get Key Redis').first().json.value;
let contactData;

if (!redisOutput) {
  contactData = { messages: [], lastMessageTimestamp: 0 };
} else {
  contactData = JSON.parse(redisOutput);
}

// Accedemos al cuerpo del webhook
const webhookBody = $('Webhook').first().json.body;
const customData = webhookBody.customData;

// Verificamos si hay una URL de imagen en 'message_attachments'
if (customData.message_attachments && customData.message_attachments !== "") {
  // Si hay imagen, la guardamos como un objeto de tipo 'image'
  const imageObject = {
    type: 'image',
    content: customData.message_attachments
  };
  contactData.messages.push(imageObject);

  // Verificamos si también hay un pie de foto en 'message_body'
  if (customData.message_body && customData.message_body !== "") {
    // Limpiamos el texto del pie de foto por si aún contiene el prefijo
    const cleanedCaption = customData.message_body.replace('type message: image\n\n', '');

    // Guardamos el pie de foto como un objeto de tipo 'text'
    const captionObject = {
      type: 'text',
      content: cleanedCaption
    };
    contactData.messages.push(captionObject);
  }
} else {
  // Si no hay adjunto, es un mensaje de solo texto
  const textObject = {
    type: 'text',
    content: customData.message_body
  };
  contactData.messages.push(textObject);
}

// Actualizamos el timestamp como antes
contactData.lastMessageTimestamp = Date.now();

// Preparamos la salida para guardar en Redis
return {
  // Usamos el contact_id del nivel principal del body
  contactId: webhookBody.contact_id,
  updatedDataString: JSON.stringify(contactData),
  executionTimestamp: contactData.lastMessageTimestamp
};

// Paso 1: Leer y parsear el input como antes.
const inputItem = $input.first().json;
const cachedData = JSON.parse(inputItem.value);
const messages = cachedData.messages;

const finalOutput = [];
let i = 0; // Usaremos un contador manual para poder saltar elementos.

while (i < messages.length) {
  const currentMessage = messages[i];

  if (currentMessage.type === 'text') {
    // --- MANEJO DE BLOQUES DE TEXTO ---
    // Si encontramos texto, empezamos a acumularlo.
    let textBuffer = [currentMessage.content];
    let nextIndex = i + 1;

    // Seguimos acumulando mientras los siguientes mensajes también sean de texto.
    while (nextIndex < messages.length && messages[nextIndex].type === 'text') {
      textBuffer.push(messages[nextIndex].content);
      nextIndex++;
    }

    // Creamos un item de solo texto con todo lo acumulado.
    finalOutput.push({
      imageUrl: null,
      associatedText: textBuffer.join(' ')
    });

    // Actualizamos el contador principal para saltar los textos ya procesados.
    i = nextIndex;

  } else if (currentMessage.type === 'image') {
    // --- MANEJO DE PARES IMAGEN -> TEXTO ---
    let associatedText = "";

    // Verificamos si el siguiente mensaje es un texto (el pie de foto).
    if ((i + 1) < messages.length && messages[i + 1].type === 'text') {
      associatedText = messages[i + 1].content;
      i++; // Incrementamos el contador para saltar el pie de foto.
    }

    finalOutput.push({
      imageUrl: currentMessage.content,
      associatedText: associatedText
    });

    i++; // Pasamos al siguiente mensaje.
  } else {
    // Por si acaso hay otros tipos de mensajes en el futuro, los ignoramos.
    i++;
  }
}

// Devolvemos el resultado en el formato que n8n espera.
return finalOutput.map(item => ({ json: item }));

